-- BUG-027: Persisted cheating_violations rows are the source of truth.
-- `event_id` is generated by the browser and makes retrying the same event safe.
-- Run this entire file in Supabase SQL Editor, then run
-- backend/scripts/verify-monitoring-schema.sql. Existing records are preserved.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

ALTER TABLE public.cheating_violations
  ADD COLUMN IF NOT EXISTS event_id text;

-- These columns are a cached summary only. Event detail remains in
-- cheating_violations and must never be reconstructed from client input.
ALTER TABLE public.quiz_attempts
  ADD COLUMN IF NOT EXISTS violation_count integer NOT NULL DEFAULT 0;

ALTER TABLE public.quiz_attempts
  ADD COLUMN IF NOT EXISTS violations jsonb NOT NULL DEFAULT '[]'::jsonb;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM (VALUES
      ('cheating_violations', 'event_id', 'text'::regtype),
      ('quiz_attempts', 'violation_count', 'integer'::regtype),
      ('quiz_attempts', 'violations', 'jsonb'::regtype)
    ) AS required(table_name, column_name, expected_type)
    WHERE NOT EXISTS (
      SELECT 1 FROM pg_attribute a
      WHERE a.attrelid = to_regclass('public.' || required.table_name)
        AND a.attname = required.column_name AND NOT a.attisdropped
        AND a.atttypid = required.expected_type
    )
  ) THEN
    RAISE EXCEPTION 'Monitoring columns have incompatible types. Review the schema before retrying migration 019; no records have been converted.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.cheating_violations WHERE event_id IS NOT NULL AND quiz_attempt_id IS NOT NULL
    GROUP BY quiz_attempt_id, event_id HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Duplicate monitoring event IDs require review before migration 019. No events have been deleted.';
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS cheating_violations_attempt_event_id_unique
  ON public.cheating_violations (quiz_attempt_id, event_id)
  WHERE event_id IS NOT NULL;

-- IF NOT EXISTS alone would silently accept an incorrectly defined old index.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_index i
    JOIN pg_attribute attempt ON attempt.attrelid = i.indrelid
      AND attempt.attname = 'quiz_attempt_id' AND NOT attempt.attisdropped
    JOIN pg_attribute event ON event.attrelid = i.indrelid
      AND event.attname = 'event_id' AND NOT event.attisdropped
    WHERE i.indexrelid = to_regclass('public.cheating_violations_attempt_event_id_unique')
      AND i.indrelid = 'public.cheating_violations'::regclass
      AND i.indisunique AND i.indisvalid AND i.indisready AND i.indnkeyatts = 2
      AND i.indkey[0] = attempt.attnum AND i.indkey[1] = event.attnum
      AND regexp_replace(pg_get_expr(i.indpred, i.indrelid), '[[:space:]()]', '', 'g') = 'event_idISNOTNULL'
  ) THEN
    RAISE EXCEPTION 'The monitoring retry index has an incompatible definition. Review cheating_violations_attempt_event_id_unique before retrying migration 019.';
  END IF;
END $$;

-- Defaults affect future inserts only; do not overwrite historical summaries.
ALTER TABLE public.quiz_attempts ALTER COLUMN violation_count SET DEFAULT 0;
ALTER TABLE public.quiz_attempts ALTER COLUMN violations SET DEFAULT '[]'::jsonb;

NOTIFY pgrst, 'reload schema';
COMMIT;
